AVOGADRO_CM3 = 6.02214076e23
BOHR_RADIUS_NM = 0.0529177210903
COULOMB_COEFF_EV_NM = 1.44
DAMAGE_AMORPHIZATION_THRESHOLD = 8.0e21
ION_ENERGY_CUTOFF_EV = 80.0


def _canonical_species_key(species: str) -> str:
    key = str(species).strip().lower().replace(" ", "")
    while key and key[-1] in {"+", "-"}:
        key = key[:-1]
    return key


def _canonical_species_symbol(species: str) -> str:
    return _canonical_species_key(species).upper()


def _species_params(species: str) -> Dict[str, float]:
    species_key = _canonical_species_key(species)
    record = IMPLANT_SPECIES_DB.get(species_key)
    if record is not None:
        return record
    return {"mass_amu": 40.0, "atomic_number": 20, "stopping_prefactor": 1.0}


def _target_params(material: Material) -> Dict[str, float]:
    record = IMPLANT_TARGET_DB.get(material.name)
    if record is not None:
        return record
    return {
        "mass_amu": max(material.density * 10.0, 30.0),
        "atomic_number": 14.0,
        "displacement_e_ev": 18.0,
    }


def _screening_length_nm(z1: float, z2: float) -> float:
    return 0.8854 * BOHR_RADIUS_NM / (z1 ** 0.23 + z2 ** 0.23)


def _nuclear_cross_section_nm2(z1: float, z2: float, energy_ev: float, screening_nm: float) -> float:
    kappa = (COULOMB_COEFF_EV_NM * z1 * z2) / max(energy_ev, 1e-3)
    sigma = math.pi * screening_nm * screening_nm * (1.0 + (kappa / max(screening_nm, 1e-6)) ** 2)
    return max(sigma, 1e-6)


def _electron_stopping_ev_per_nm(prefactor: float, z1: float, z2: float, energy_ev: float) -> float:
    energy_ev = max(energy_ev, 1.0)
    return prefactor * (z1 ** 0.45) * (z2 ** 0.3) * math.sqrt(energy_ev) * 1e-3


def _kinchin_pease_defects(energy_transfer_ev: float, displacement_e_ev: float) -> float:
    if energy_transfer_ev <= displacement_e_ev:
        return 0.0
    if energy_transfer_ev <= 2.0 * displacement_e_ev:
        return 1.0
    return energy_transfer_ev / (2.0 * displacement_e_ev)


def _random_unit_vector_within_cone(center: np.ndarray, spread_rad: float, rng: np.random.Generator) -> np.ndarray:
    if spread_rad <= 1e-6:
        vec = np.array(center, dtype=np.float64, copy=True)
        return vec / np.linalg.norm(vec)
    center_vec = np.array(center, dtype=np.float64, copy=True)
    center_vec /= np.linalg.norm(center_vec)
    u = rng.random()
    v = rng.random()
    cos_theta = 1.0 - u * (1.0 - math.cos(spread_rad))
    sin_theta = math.sqrt(max(0.0, 1.0 - cos_theta * cos_theta))
    phi = 2.0 * math.pi * v
    orth = np.cross(center_vec, np.array([0.0, 0.0, 1.0]))
    if np.linalg.norm(orth) < 1e-6:
        orth = np.cross(center_vec, np.array([0.0, 1.0, 0.0]))
    orth /= np.linalg.norm(orth)
    second = np.cross(center_vec, orth)
    second /= np.linalg.norm(second)
    rotation = (
        cos_theta * center_vec
        + sin_theta * (math.cos(phi) * orth + math.sin(phi) * second)
    )
    return rotation / np.linalg.norm(rotation)


