def fibonacci_hemisphere(num_samples: int) -> np.ndarray:
    num_samples = max(1, int(num_samples))
    pts = np.zeros((num_samples, 3), dtype=np.float64)
    offset = 2.0 / num_samples
    increment = math.pi * (3.0 - math.sqrt(5.0))
    idx = 0
    for i in range(num_samples * 2):
        y = ((i * offset) - 1.0) + offset / 2.0
        r = math.sqrt(max(0.0, 1.0 - y * y))
        phi = i * increment
        x = math.cos(phi) * r
        z = math.sin(phi) * r
        if z <= 0.0:
            continue
        pts[idx] = (x, y, z)
        idx += 1
        if idx >= num_samples:
            break
    if idx < num_samples:
        pts = pts[:idx]
    norms = np.linalg.norm(pts, axis=1, keepdims=True)
    norms[norms == 0.0] = 1.0
    return pts / norms


# GUI stack (optional): allow running the WebUI + headless selftests without PyQt5.
_HAS_QT = False
try:  # pragma: no cover - optional dependency
    # IMPORTANT: never import the Qt GUI stack in spawned/forked child processes.
    # - WebUI worker sessions use multiprocessing and do not require any Qt classes.
    # - Frozen builds (Nuitka/PyInstaller) are especially sensitive: importing Qt in a child
    #   process can crash or exit early, leading to WebUI errors like:
    #     "Worker died while processing cmd=init"
    # Keep Qt imports confined to the main process only.
    _skip_qt = False
    try:
        if str(os.environ.get("TCAD_SKIP_QT", "") or "").strip().lower() in {"1", "true", "yes", "y", "on"}:
            _skip_qt = True
    except Exception:
        pass
    try:
        # Most reliable: multiprocessing "spawn" children include a forking sentinel in argv.
        # (Works in frozen builds where current_process().name can still be "MainProcess" during import.)
        from multiprocessing import spawn as _mp_spawn  # local import (stdlib)

        if hasattr(_mp_spawn, "is_forking") and _mp_spawn.is_forking(sys.argv):
            _skip_qt = True
    except Exception:
        pass
    try:
        # Python 3.8+: child processes can also be detected via parent_process().
        if multiprocessing.parent_process() is not None:
            _skip_qt = True
    except Exception:
        pass
    if not _skip_qt:
        try:
            _skip_qt = multiprocessing.current_process().name != "MainProcess"
        except Exception:
            # If process identity cannot be determined, default to importing Qt (best for dev).
            _skip_qt = False
    if _skip_qt:
        raise ImportError("Skip Qt import in child process")
    from PyQt5 import QtCore, QtGui, QtWidgets  # type: ignore
    from matplotlib.backends.backend_qt5agg import FigureCanvasQTAgg  # type: ignore

    _HAS_QT = True
except Exception:  # pragma: no cover
    _HAS_QT = False

    class _QtStubType(type):
        """Create dummy Qt classes/enums on demand (headless WebUI-only execution)."""

        def __getattr__(cls, name: str) -> Any:
            t = type(name, (), {})
            setattr(cls, name, t)
            return t

    class _QtStub(metaclass=_QtStubType):
        def __init__(self, *args: Any, **kwargs: Any) -> None:
            _ = (args, kwargs)

        def __call__(self, *args: Any, **kwargs: Any) -> "_QtStub":
            _ = (args, kwargs)
            return self

        def __getattr__(self, name: str) -> Any:
            # Most uses are as base classes (QtWidgets.QWidget) or enums (QtCore.Qt.*).
            t = type(name, (), {})
            setattr(self.__class__, name, t)
            return t

        def __bool__(self) -> bool:
            return False

        def __or__(self, other: Any) -> Any:
            return self

        __ror__ = __or__

        def __and__(self, other: Any) -> Any:
            return self

        __rand__ = __and__

        def __int__(self) -> int:
            return 0

        def __float__(self) -> float:
            return 0.0

    QtCore = _QtStub()  # type: ignore
    QtGui = _QtStub()  # type: ignore
    QtWidgets = _QtStub()  # type: ignore

    class FigureCanvasQTAgg:  # type: ignore
        def __init__(self, *args: Any, **kwargs: Any) -> None:
            _ = (args, kwargs)

# Matplotlib backend: ensure headless backend in non-Qt contexts (e.g., WebUI workers).
try:
    if not bool(globals().get("_HAS_QT", False)):
        os.environ.setdefault("MPLBACKEND", "Agg")
except Exception:
    pass

