    class SurfaceComponentResult:
        component_index: int = 0
        vertices: np.ndarray = field(default_factory=lambda: np.empty((0, 3), dtype=np.float64))
        faces: np.ndarray = field(default_factory=lambda: np.empty((0, 3), dtype=np.int32))
        brep_solid: Any = None

    class AdvancedSurfaceReconstructor:
        def __init__(self, voxel_size_nm: float = 5.0) -> None:
            self.voxel_size_nm = float(voxel_size_nm)

        @property
        def open3d_ready(self) -> bool:
            return False

        @property
        def brep_ready(self) -> bool:
            return False

        def build_component(
            self,
            global_coords: np.ndarray,
            options: ReconstructionOptions,
            component_index: int = 0,
        ) -> Optional[SurfaceComponentResult]:
            _ = (global_coords, options, component_index)
