class SelectiveEpitaxyStep(ProcessStep):
    name = "Selective Epitaxy"
    group = "Deposition"

    def parameter_specs(self) -> Sequence[ParameterSpec]:
        epi_targets = [
            (mat.name, mat.name)
            for _, mat in self.material_db.items()
            if mat.name not in {"Void"} and mat.surface_group == "Semiconductor"
        ]
        seed_rules = [
            ("Semiconductor", "All semiconductors (default)"),
            ("Silicon only", "Silicon only"),
            ("Si/Poly/SiGe", "Silicon + Polysilicon + SiGe"),
            ("Custom", "Custom list (seed_materials)"),
        ]
        return (
            ParameterSpec("material", "Epitaxial material", "enum", "SiGe", choices=epi_targets),
            ParameterSpec("thickness", "Thickness", "float", 20.0, 0.0, 5000.0, units="nm"),
            ParameterSpec("temperature", "Temperature", "float", 650.0, 400.0, 1100.0, units="°C"),
            ParameterSpec(
                "directionality",
                "Directionality",
                "float",
                0.1,
                0.0,
                1.0,
                decimals=2,
                tooltip="Higher values make growth more line-of-sight (less conformal).",
            ),
            ParameterSpec(
                "gap_fill_bias",
                "Gap-fill bias",
                "float",
                0.0,
                -500.0,
                1000.0,
                units="nm",
                tooltip="Positive biases boost growth deeper in high-aspect-ratio features (super-conformal).",
            ),
            ParameterSpec("seed_rule", "Seed rule", "enum", "Semiconductor", choices=seed_rules),
            ParameterSpec(
                "seed_materials",
                "Seed materials (CSV)",
                "text",
                "",
                tooltip="Used when seed_rule=Custom. Format: Silicon, Polysilicon, 3 (mat_id) ...",
            ),
            ParameterSpec("doping", "In-situ doping", "text", "B:1e19", tooltip="Species:concentration (cm^-3), comma separated."),
        )

    def execute(self, model: ProcessModel) -> str:
        material_name = _resolve_material_name_any(model.material_db, self.params.get("material")) or "SiGe"
        material_id = model.material_db.id_for(material_name)
        seed_rule = str(self.params.get("seed_rule", "Semiconductor") or "Semiconductor").strip()
        seed_ids: Optional[List[int]] = None
        if seed_rule == "Silicon only":
            try:
                seed_ids = [int(model.material_db.id_for("Silicon"))]
            except Exception:
                seed_ids = None
        elif seed_rule == "Si/Poly/SiGe":
            seed_ids = []
            for nm in ("Silicon", "Polysilicon", "SiGe"):
                try:
                    seed_ids.append(int(model.material_db.id_for(nm)))
                except Exception:
                    continue
            if not seed_ids:
                seed_ids = None
        elif seed_rule == "Custom":
            raw = str(self.params.get("seed_materials", "") or "")
            parts = [p.strip() for p in raw.replace(";", ",").split(",") if p.strip()]
            ids: List[int] = []
            for p in parts:
                mid = _resolve_material_id_any(model.material_db, p)
                if mid is not None:
                    ids.append(int(mid))
            seed_ids = ids if ids else None
        model.deposit_material(
            material_name,
            self.params["thickness"],
            method="Epitaxy",
            coverage="Open mask",
            temperature_c=self.params["temperature"],
            directionality=self.params.get("directionality", 0.1),
            gap_fill_bias_nm=self.params.get("gap_fill_bias", 0.0),
            epi_seed_material_ids=seed_ids,
        )
        dopants = self.params.get("doping", "")
        if dopants:
            self._apply_in_situ_doping(model, material_id, dopants)
        return f"Selective epitaxy {material_name}"

    def _apply_in_situ_doping(self, model: ProcessModel, material_id: int, dopants: str) -> None:
        entries = [token.strip() for token in dopants.split(",") if token.strip()]
        lattice_species: Optional[str] = None
        try:
            model._ensure_doping_field()
        except Exception:
            return
        mask = model.open_mask
        xs, ys = np.where(mask)
        for entry in entries:
            if ":" not in entry:
                continue
            species, conc = entry.split(":", 1)
            try:
                conc_val = float(conc)
            except ValueError:
                continue
            elem = model._dopant_element_symbol(species)
            try:
                species_field = model._ensure_dopant_species_field(elem)
            except Exception:
                species_field = None
            for x, y in zip(xs, ys):
                height = int(model.height_map[x, y])
                if height <= 0:
                    continue
                z = height - 1
                while z >= 0 and int(model.grid[x, y, z]) == material_id:
                    existing = model.doping[x, y, z]
                    model.doping[x, y, z] = max(existing, conc_val)
                    if isinstance(species_field, np.ndarray):
                        try:
                            species_field[x, y, z] = max(float(species_field[x, y, z]), float(conc_val))
                        except Exception:
                            pass
                    z -= 1
            if not lattice_species:
                lattice_species = species.strip().upper()
        if lattice_species:
            model.last_implant_species = lattice_species


