class ThinningStep(ProcessStep):
    name = "Thinning"
    group = "Wafer"

    def parameter_specs(self) -> Sequence[ParameterSpec]:
        materials = [(name, name) for name in self.material_db.names() if name != "Void"]
        return (
            ParameterSpec(
                "target_thickness_nm",
                "Target remaining thickness",
                "float",
                50.0,
                0.001,
                10000.0,
                units="nm",
            ),
            ParameterSpec(
                "material",
                "Target material",
                "enum",
                "Silicon",
                choices=materials,
                tooltip=(
                    "Selectively removes only this material from backside-facing layers; "
                    "non-target cap material is preserved."
                ),
            ),
        )

    def execute(self, model: ProcessModel) -> str:
        material_id, material_name = _normalize_nonvoid_material(
            model.material_db,
            self.params.get("material"),
            "Thinning",
        )
        removed = model.thin_wafer(
            self.params.get("target_thickness_nm"),
            material_id,
        )
        return f"Thinning {material_name}: removed {removed} voxels from backside"


class EtchStep(ProcessStep):
    name = "Etch"
    group = "Etch"

    def parameter_specs(self) -> Sequence[ParameterSpec]:
        materials = [(name, name) for name in self.material_db.names() if name not in {"Void"}]
        chemistries = [
            ("Dry", "Dry"),
            ("Plasma", "Plasma"),
            ("Wet", "Wet"),
            ("TMAH", "TMAH (anisotropic Si)"),
            ("KOH", "KOH (anisotropic Si)"),
            ("VHF", "VHF"),
            ("HotPhosphoric", "Hot phosphoric"),
            ("O2", "O₂ strip"),
        ]
        return (
            ParameterSpec("material", "Target material", "enum", "Silicon", choices=materials),
            ParameterSpec("chemistry", "Chemistry", "enum", "Dry", choices=chemistries),
            ParameterSpec(
                "rate_model",
                "Rate model",
                "enum",
                "Advanced",
                choices=[
                    ("Advanced", "Advanced (physics proxy)"),
                    ("RateTable", "Scale to material etch_rates"),
                ],
                tooltip="Advanced uses the built-in plasma proxy model. RateTable scales the dry-etch kernel so the mean vertical rate matches Material.etch_rates_nm_min[chemistry] when available (keeps geometry effects).",
            ),
            ParameterSpec("time", "Etch time", "float", 30.0, 0.0, 10000.0, units="s"),
            ParameterSpec("bias", "Etch bias", "float", 0.0, -1000.0, 1000.0, units="nm"),
            ParameterSpec(
                "rate_override",
                "Override rate",
                "float",
                0.0,
                0.0,
                20000.0,
                units="Å/min",
                tooltip="Optional: directly specify vertical etch rate in Å/min (0 = use material database).",
            ),
            ParameterSpec("selectivity", "Selectivity to resist", "float", 4.0, 0.01, 500.0),
            ParameterSpec("sidewall", "Sidewall angle", "float", 88.0, 30.0, 90.0, units="°"),
            ParameterSpec(
                "co_materials",
                "Multi-material selectivity",
                "text",
                "",
                tooltip="Format: Material:ratio;Material2:ratio (ratio relative to anchor material).",
            ),
            ParameterSpec("pressure", "Pressure", "float", 15.0, 1.0, 200.0, units="mTorr"),
            ParameterSpec("rf_bias", "RF bias", "float", 180.0, 10.0, 1000.0, units="V"),
            ParameterSpec("neutral_flux", "Neutral flux scale", "float", 1.0, 0.1, 5.0, decimals=2),
            ParameterSpec("passivation", "Passivation rate", "float", 0.2, 0.0, 2.0, decimals=2),
            ParameterSpec(
                "stop_on_material",
                "Stop on material (optional)",
                "enum",
                "",
                choices=materials,
                tooltip="If set, the etch will never remove this material (useful as an explicit stop layer in multi-material selectivity mode).",
            ),
        )

    def execute(self, model: ProcessModel) -> str:
        mat_name = _resolve_material_name_any(model.material_db, self.params.get("material")) or "Silicon"
        additional = parse_selectivity(self.params.get("co_materials", ""), self.material_db)
        stop_on = self.params.get("stop_on_material", "")
        model.etch_material(
            mat_name,
            self.params["chemistry"],
            self.params["time"],
            self.params["bias"],
            self.params.get("rate_override", 0.0),
            self.params["selectivity"],
            self.params["sidewall"],
            co_material_selectivity=additional,
            pressure_mtorr=self.params["pressure"],
            bias_voltage_v=self.params["rf_bias"],
            neutral_flux_scale=self.params["neutral_flux"],
            passivation_rate=self.params["passivation"],
            rate_model=self.params.get("rate_model", "Advanced"),
            stop_on_material=stop_on,
        )
        return f"Etch {mat_name}"


class CMPProcessStep(ProcessStep):
    name = "CMP"
    group = "Planarization"

    def __init__(self, material_db: MaterialDatabase) -> None:
        super().__init__(material_db)
        self.params.setdefault(
            "selectivity_pairs",
            [
                {"material": "Copper", "ratio": 1.0},
                {"material": "Silicon Dioxide", "ratio": 0.3},
            ],
        )

    def parameter_specs(self) -> Sequence[ParameterSpec]:
        mats = [(name, name) for name in self.material_db.names() if name not in {"Void"}]
        sel_modes = [
            ("Manual", "Manual list (selectivity_pairs)"),
            ("MaterialDB", "From Material DB (cmp_selectivity)"),
        ]
        return (
            ParameterSpec("target", "Target height", "float", 300.0, 0.0, 10000.0, units="nm"),
            ParameterSpec("pressure", "Pressure", "float", 3.0, 0.0, 100.0, units="psi"),
            ParameterSpec("time", "Time", "float", 60.0, 0.0, 10000.0, units="s"),
            ParameterSpec("preston", "Preston coeff", "float", 0.3, 0.0001, 2.0, units="nm/(psi·s)", decimals=4),
            ParameterSpec(
                "selectivity_mode",
                "Selectivity mode",
                "enum",
                "Manual",
                choices=sel_modes,
                tooltip="Manual uses selectivity_pairs; MaterialDB derives ratios from Material.cmp_selectivity[target_material].",
            ),
            ParameterSpec("target_material", "Target material (for MaterialDB)", "enum", "Silicon Dioxide", choices=mats),
        )

    def execute(self, model: ProcessModel) -> str:
        mode = str(self.params.get("selectivity_mode", "Manual") or "Manual").strip()
        selectivity_spec: Any = self.params.get("selectivity_pairs")
        legacy = self.params.get("selectivity")
        if isinstance(legacy, str) and legacy.strip():
            selectivity_spec = legacy
        if mode == "MaterialDB":
            target_name = _resolve_material_name_any(model.material_db, self.params.get("target_material")) or "Silicon Dioxide"
            # Build "listed materials only" dict. Missing entries remain stop (0).
            sel: Dict[str, float] = {}
            for _mid, mat in model.material_db.items():
                if mat.name == "Void":
                    continue
                if mat.name == target_name:
                    sel[mat.name] = 1.0
                    continue
                try:
                    ratio = float((mat.cmp_selectivity or {}).get(target_name, 0.0))
                except Exception:
                    ratio = 0.0
                if math.isfinite(ratio) and ratio > 0.0:
                    sel[mat.name] = float(ratio)
            selectivity_spec = sel
        model.cmp(
            self.params["target"],
            self.params["pressure"],
            self.params["time"],
            self.params["preston"],
            selectivity_spec,
        )
        return f"CMP to {self.params['target']:.0f} nm"


