_WEBUI_COOKIE_NAME = "tcad_session"


def _webui_timestamp() -> str:
    t = time.time()
    base = time.strftime("%Y%m%d_%H%M%S", time.localtime(t))
    ms = int((t - math.floor(t)) * 1000.0)
    return f"{base}_{ms:03d}"


def _webui_safe_filename(name: str, suffix: str = "") -> str:
    safe = "".join(ch if ch.isalnum() or ch in {"_", "-", "."} else "_" for ch in str(name)).strip("._")
    if not safe:
        safe = "file"
    if suffix and not safe.endswith(suffix):
        safe += suffix
    return safe


def _webui_normalize_quality(value: Any) -> str:
    v = str(value or "").strip().lower()
    if v in {"low", "l", "0"} or v.startswith("low"):
        return "low"
    if v in {"medium", "med", "m", "1"} or v.startswith("med") or v.startswith("mid"):
        return "medium"
    if v in {"high", "h", "2"} or v.startswith("high"):
        return "high"
    return "high"


def _webui_pickle_dump(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    # Speed-first: WebUI autosaves can be frequent; keep gzip level low to avoid UI stalls.
    with gzip.open(tmp, "wb", compresslevel=1) as fh:
        pickle.dump(payload, fh, protocol=pickle.HIGHEST_PROTOCOL)
    tmp.replace(path)


def _webui_pickle_load(path: Path) -> Any:
    with gzip.open(path, "rb") as fh:
        return pickle.load(fh)


def _tcad_geom_bytes_to_binary_stl(geom_bytes: bytes, *, header_name: str = "TCAD") -> bytes:
    """Convert a TCAD `.geom` payload (indexed mesh) into a binary STL (fast fallback)."""

    data = bytes(geom_bytes)
    if len(data) < 24:
        raise ValueError("geom too small")
    magic, version, flags, vcount, icount = struct.unpack("<8sIIII", data[:24])
    if magic != b"TCADGEOM" or int(version) != 1:
        raise ValueError("bad geom header")
    off = 24
    pos = np.frombuffer(data, dtype=np.float32, count=int(vcount) * 3, offset=off).reshape((-1, 3))
    off += int(vcount) * 3 * 4
    if int(flags) & 2:
        # Vertex normals exist; skip (STL stores per-face normals; we recompute from geometry).
        off += int(vcount) * 3 * 4
    idx = np.frombuffer(data, dtype=np.uint32, count=int(icount), offset=off).reshape((-1, 3))
    tris = pos[idx].astype(np.float32, copy=False)
    if tris.size == 0:
        # Valid empty STL.
        header = (str(header_name or "TCAD").encode("ascii", "ignore")[:80]).ljust(80, b" ")
        return header + struct.pack("<I", 0)

    v01 = tris[:, 1, :] - tris[:, 0, :]
    v02 = tris[:, 2, :] - tris[:, 0, :]
    n = np.cross(v01, v02)
    nrm = np.linalg.norm(n, axis=1, keepdims=True)
    n = (n / np.maximum(nrm, 1e-12)).astype(np.float32, copy=False)

    tri_dtype = np.dtype(
        [
            ("normal", "<f4", (3,)),
            ("v0", "<f4", (3,)),
            ("v1", "<f4", (3,)),
            ("v2", "<f4", (3,)),
            ("attr", "<u2"),
        ]
    )
    out = np.zeros(int(tris.shape[0]), dtype=tri_dtype)
    out["normal"] = n
    out["v0"] = tris[:, 0, :]
    out["v1"] = tris[:, 1, :]
    out["v2"] = tris[:, 2, :]
    out["attr"] = 0

    header = (str(header_name or "TCAD").encode("ascii", "ignore")[:80]).ljust(80, b" ")
    return header + struct.pack("<I", int(tris.shape[0])) + out.tobytes(order="C")


def _webui_download_to_path(url: str, dest: Path, *, timeout_s: float = 30.0) -> None:
    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp = dest.with_suffix(dest.suffix + ".tmp")
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": "TCAD-WebUI/1.0",
            "Accept": "*/*",
        },
    )
    # macOS packaged builds: avoid `getproxies_macosx_sysconf` (SystemConfiguration) crashes by
    # disabling system proxy auto-detection by default. Re-enable via env var if needed.
    use_system_proxies = False
    try:
        v = str(os.environ.get("TCAD_WEBUI_USE_SYSTEM_PROXIES", os.environ.get("TCAD_AGENT_USE_SYSTEM_PROXIES", "")) or "").strip().lower()
        use_system_proxies = v in {"1", "true", "yes", "on"}
    except Exception:
        use_system_proxies = False
    ssl_ctx: Any = None
    try:
        if str(url).lower().startswith("https://"):
            import ssl  # local import

            try:
                import certifi  # type: ignore[import-not-found]

                ssl_ctx = ssl.create_default_context(cafile=certifi.where())
            except Exception:
                ssl_ctx = ssl.create_default_context()
    except Exception:
        ssl_ctx = None
    if (sys.platform == "darwin") and (not use_system_proxies):
        handlers: List[Any] = [urllib.request.ProxyHandler({})]
        try:
            if ssl_ctx is not None and str(url).lower().startswith("https://"):
                handlers.append(urllib.request.HTTPSHandler(context=ssl_ctx))
        except Exception:
            pass
        opener = urllib.request.build_opener(*handlers)
        with opener.open(req, timeout=float(timeout_s)) as resp:
            data = resp.read()
    else:
        with urllib.request.urlopen(req, timeout=float(timeout_s), context=ssl_ctx) as resp:
            data = resp.read()
    if not data:
        raise RuntimeError(f"Empty download: {url}")
    tmp.write_bytes(data)
    tmp.replace(dest)


def _webui_guess_lan_ip() -> str:
    """Best-effort LAN IPv4 address for display/opening browser URLs."""

    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
            s.settimeout(0.5)
            s.connect(("8.8.8.8", 80))
            ip = s.getsockname()[0]
            if ip and not ip.startswith("127."):
                return ip
    except Exception:
        pass
    try:
        ip = socket.gethostbyname(socket.gethostname())
        if ip and not ip.startswith("127."):
            return ip
    except Exception:
        pass
    return "127.0.0.1"


def _webui_launch_root() -> Path:
    """Return the directory used as the app 'launch root' for WebUI assets and TCAD_Web_Data.

    - Source run: folder containing `tcad_simulator.py`.
    - Packaged run (e.g., Nuitka standalone): folder containing the executable.
    - Fallback: current working directory.
    """

    # Allow explicit override for advanced deployments/tests where the entrypoint is a wrapper
    # script (sys.argv[0] would otherwise point to the wrapper directory).
    try:
        env = str(os.environ.get("TCAD_LAUNCH_ROOT", "") or "").strip()
        if env:
            p = Path(env).expanduser()
            try:
                p = p.resolve()
            except Exception:
                p = Path(os.path.abspath(str(p)))
            if p.exists():
                return p.parent if p.is_file() else p
    except Exception:
        pass

    # Prefer the directory of the entrypoint executable/script when it is not the system Python.
    #
    # Nuitka onefile note:
    # - `sys.executable` can point to the *temporary extracted* executable location.
    # - `sys.argv[0]` tends to preserve the original program path used to launch the app.
    # Using argv0 first keeps TCAD_Web_Data persistent next to the original exe when writable.
    try:
        argv0 = sys.argv[0] if sys.argv else ""
        if argv0:
            p = Path(argv0)
            try:
                p = p.resolve()
            except Exception:
                p = Path(os.path.abspath(argv0))
            if p.exists():
                name = p.name.lower()
                if name not in {
                    "python",
                    "python3",
                    "pythonw",
                    "python.exe",
                    "python3.exe",
                    "pythonw.exe",
                    "pytest",
                    "pytest.exe",
                }:
                    # If launched via a wrapper *.py (e.g., automation/launcher scripts), prefer
                    # this module's directory so WebUI assets + `LLM_Test_Config.json` are found
                    # without requiring `TCAD_LAUNCH_ROOT`.
                    try:
                        this_name = Path(__file__).name.lower()
                    except Exception:
                        this_name = ""
                    try:
                        is_wrapper_py = bool(
                            p.is_file()
                            and p.suffix.lower() in {".py", ".pyw"}
                            and this_name
                            and name != this_name
                        )
                    except Exception:
                        is_wrapper_py = False
                    if not is_wrapper_py:
                        return p.parent if p.is_file() else p
    except Exception:
        pass

    # Frozen executable fallback: sys.executable is the most reliable anchor when argv0 is missing.
    try:
        if bool(getattr(sys, "frozen", False)) or bool(globals().get("__compiled__", False)):
            ex = str(getattr(sys, "executable", "") or "").strip()
            if ex:
                p = Path(ex).expanduser()
                try:
                    p = p.resolve()
                except Exception:
                    p = Path(os.path.abspath(str(p)))
                if p.exists():
                    return p.parent if p.is_file() else p
    except Exception:
        pass

    try:
        return Path(__file__).resolve().parent
    except Exception:
        return Path.cwd()


def _tcad_user_data_root(app_name: str = "TCAD_Simulator") -> Path:
    """Best-effort user-writable data root for packaged deployments.

    Windows: %LOCALAPPDATA%/<app_name>
    macOS:   ~/Library/Application Support/<app_name>
    Linux:   ${XDG_DATA_HOME:-~/.local/share}/<app_name>
    """
    name = str(app_name or "TCAD_Simulator").strip() or "TCAD_Simulator"
    try:
        if os.name == "nt":
            base = os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA")
            if base:
                return (Path(base).expanduser() / name).resolve()
            return (Path.home() / "AppData" / "Local" / name).resolve()
        if sys.platform == "darwin":
            return (Path.home() / "Library" / "Application Support" / name).resolve()
        # Linux / other
        base = os.environ.get("XDG_DATA_HOME")
        if base:
            return (Path(base).expanduser() / name).resolve()
        return (Path.home() / ".local" / "share" / name).resolve()
    except Exception:
        return (Path.home() / f".{name}").resolve()


def _tcad_ensure_writable_dir(p: Path) -> Optional[Path]:
    """Try to create and write into `p`; return `p` if writable else None."""
    try:
        p = Path(p).expanduser()
        try:
            p = p.resolve()
        except Exception:
            p = Path(os.path.abspath(str(p)))
        p.mkdir(parents=True, exist_ok=True)
        probe = p / f".write_probe_{os.getpid()}_{secrets.token_hex(4)}"
        probe.write_text("ok", encoding="utf-8")
        try:
            probe.unlink()
        except Exception:
            pass
        return p
    except Exception:
        return None


def _tcad_default_webui_storage_root() -> Path:
    """Default storage root for TCAD WebUI sessions/logs/exports."""
    try:
        env = str(os.environ.get("TCAD_WEBUI_STORAGE_ROOT", "") or os.environ.get("TCAD_STORAGE_ROOT", "") or "").strip()
    except Exception:
        env = ""
    if env:
        return Path(env).expanduser()
    packaged = False
    try:
        packaged = bool(getattr(sys, "frozen", False)) or bool(globals().get("__compiled__", False)) or bool(os.environ.get("NUITKA_ONEFILE_PARENT"))
    except Exception:
        packaged = False
    if packaged:
        # Prefer storing next to the executable when possible (portable builds), but
        # WebUIServerManager/AdminServerManager will still fall back to user data when unwritable.
        return _webui_launch_root() / "TCAD_Web_Data"
    return _webui_launch_root() / "TCAD_Web_Data"


# ---------------------------------------------------------------------------
# Agent Skills (SKILL.md) - external knowledge packs for TCAD Agent
#
# Goals:
# - Keep the simulator single-file, but allow the agent's "thinking depth" to evolve by
#   editing external SKILL.md files (no code changes required).
# - Match the common "Agent Skills Spec" pattern: skills/<skill>/SKILL.md (YAML frontmatter + Markdown body).
# - Validate only interface standardness (required fields/types) while allowing extensions (extra keys/sections).
# ---------------------------------------------------------------------------

_TCAD_SKILLS_SPEC_VERSION = 1


def _tcad_skills_build_md(
    *,
    name: str,
    description: str,
    kind: str = "",
    tags: Optional[Sequence[str]] = None,
    triggers: Optional[Sequence[str]] = None,
    body_lines: Optional[Sequence[str]] = None,
) -> str:
    """Build a SKILL.md string (YAML frontmatter + Markdown body)."""
    nm = str(name or "").strip()
    desc = str(description or "").strip()
    kind_s = str(kind or "").strip()
    tags_l = [str(x).strip() for x in (tags or []) if str(x).strip()]
    trig_l = [str(x).strip() for x in (triggers or []) if str(x).strip()]
    body = "\n".join([str(x).rstrip() for x in (body_lines or [])]).strip()

    fm: List[str] = ["---", f"name: {nm}", f"description: {desc}", f"spec_version: {_TCAD_SKILLS_SPEC_VERSION}"]
    if kind_s:
        fm.append(f"kind: {kind_s}")
    if tags_l:
        fm.append("tags:")
        fm.extend([f"  - {t}" for t in tags_l[:80]])
    if trig_l:
        fm.append("triggers:")
        fm.extend([f"  - {t}" for t in trig_l[:120]])
    fm.append("---")
    return "\n".join(fm) + "\n\n" + (body + "\n" if body else "")


def _tcad_default_skills_dir() -> Path:
    """Default skills directory (external ./skills relative to app launch root)."""
    try:
        return (_webui_launch_root() / "skills").resolve()
    except Exception:
        return Path("skills")


