                meas_summary = str(meas.get("summary", "") or "").strip()
                assistant_reply = str(meas.get("assistant_reply", "") or "").strip() or assistant_reply
                overrides = meas.get("meta_overrides") if isinstance(meas.get("meta_overrides"), list) else []
