            if cmd == "history_load":
                entry_id = str(payload.get("id", "")).strip()
                if not entry_id:
                    raise ValueError("Missing recipe id")
                prev_name = payload.get("current_name")
                if isinstance(prev_name, str) and prev_name.strip():
                    current_recipe_name = prev_name.strip()[:80]
