                        if isinstance(mc, dict) and mc:
                            mc2 = dict(mc)
                            try:
                                if not isinstance(user_material_colors, dict):
                                    user_material_colors = {}
                                user_material_colors.update(mc2)
                            except Exception:
                                user_material_colors = mc2
