    # ---- Admin CRUD: materials + process_steps (Phase 0 -> Phase 1/2/3) ----

    def _load_admin_cfg_locked(self) -> Dict[str, Any]:
        """Load admin config under the global library lock (already held by caller)."""

        cfg = _library_load_admin_config(self.storage_root)
        cfg2, changed = _admin_config_migrate(cfg)
        if changed:
            _library_save_admin_config(self.storage_root, cfg2)
        return cfg2

    def _save_admin_cfg_locked(self, cfg: Dict[str, Any]) -> None:
        cfg2, _ = _admin_config_migrate(cfg)
        ok, errors, _warnings = _admin_config_validate(cfg2)
        if not ok:
            raise ValueError("; ".join(errors[:6]) or "Invalid admin config")
        _library_save_admin_config(self.storage_root, cfg2)

    @staticmethod
    def _parse_rgb01(value: Any) -> Optional[Tuple[float, float, float]]:
        # Accept [r,g,b] in 0..1 or 0..255, or "#RRGGBB".
        if isinstance(value, str):
            s = value.strip()
            if s.startswith("#"):
                s = s[1:]
            if len(s) == 6:
                try:
                    r = int(s[0:2], 16) / 255.0
                    g = int(s[2:4], 16) / 255.0
                    b = int(s[4:6], 16) / 255.0
                    return (float(np.clip(r, 0.0, 1.0)), float(np.clip(g, 0.0, 1.0)), float(np.clip(b, 0.0, 1.0)))
                except Exception:
                    return None
            return None
        if isinstance(value, (list, tuple)) and len(value) >= 3:
            try:
                r, g, b = float(value[0]), float(value[1]), float(value[2])
            except Exception:
                return None
            # Heuristic: treat >1 as 0..255.
            if r > 1.0 or g > 1.0 or b > 1.0:
                r /= 255.0
                g /= 255.0
                b /= 255.0
            if not (math.isfinite(r) and math.isfinite(g) and math.isfinite(b)):
                return None
            return (float(np.clip(r, 0.0, 1.0)), float(np.clip(g, 0.0, 1.0)), float(np.clip(b, 0.0, 1.0)))
        return None

    def admin_materials_list(self) -> Dict[str, Any]:
        """List materials with admin overrides/custom records (for Admin UI)."""

        lock_path = self.storage_root / "_tcad_library.lock"
        with _file_lock(lock_path, timeout_s=25.0):
            cfg = self._load_admin_cfg_locked()
            mats_cfg = cfg.get("materials", {}) if isinstance(cfg.get("materials"), dict) else {}
            overrides = mats_cfg.get("overrides", {}) if isinstance(mats_cfg.get("overrides"), dict) else {}
            custom = mats_cfg.get("custom", {}) if isinstance(mats_cfg.get("custom"), dict) else {}

            db = MaterialDatabase()
            items: List[Dict[str, Any]] = []

            # Built-in materials + whether overridden.
            for mid, mat in db.items():
                ov = overrides.get(mat.name) if isinstance(overrides, dict) else None
                items.append(
                    {
                        "kind": "builtin",
                        "key": mat.name,
                        "id": int(mid),
                        "name": mat.name,
                        "enabled": True,
                        "color": list(mat.color),
                        "density": float(getattr(mat, "density", 0.0)),
                        "refractive_index": float(getattr(mat, "refractive_index", 1.0)),
                        "absorb_coeff": float(getattr(mat, "absorb_coeff", 0.0)),
                        "surface_group": mat.surface_group,
                        "tags": list(_normalize_tags_list((ov or {}).get("tags")) or getattr(mat, "tags", []) or []),
                        "note": mat.note,
                        "etch_rates_nm_min": getattr(mat, "etch_rates_nm_min", {}),
                        "deposition_conformality": getattr(mat, "deposition_conformality", {}),
                        "cmp_selectivity": getattr(mat, "cmp_selectivity", {}),
                        "composition": getattr(mat, "composition", {}),
                        "overridden": isinstance(ov, dict) and bool(ov),
                        "override": ov if isinstance(ov, dict) else {},
                    }
                )

            # Custom materials (admin-managed).
            for key in sorted(custom.keys(), key=lambda k: str(k)):
                rec = custom.get(key)
                if not isinstance(rec, dict):
                    continue
                name = str(rec.get("name") or key).strip() or str(key)
                enabled = bool(rec.get("enabled", True))
                color = rec.get("color")
                rgb = self._parse_rgb01(color) if color is not None else None
                if rgb is None:
                    rgb = (0.8, 0.8, 0.8)
                try:
                    density = float(rec.get("density", 0.0))
                except Exception:
                    density = 0.0
                try:
                    refr = float(rec.get("refractive_index", 1.0))
                except Exception:
                    refr = 1.0
                try:
                    absorb = float(rec.get("absorb_coeff", 0.0))
                except Exception:
                    absorb = 0.0
                items.append(
                    {
                        "kind": "custom",
                        "key": str(key),
                        "id": int(rec.get("id", -1) or -1),
                        "name": name,
                        "enabled": enabled,
                        "color": [float(rgb[0]), float(rgb[1]), float(rgb[2])],
                        "density": float(density),
                        "refractive_index": float(refr),
                        "absorb_coeff": float(absorb),
                        "surface_group": str(rec.get("surface_group") or ""),
                        "tags": _normalize_tags_list(rec.get("tags")),
                        "note": str(rec.get("note") or ""),
                        "etch_rates_nm_min": rec.get("etch_rates_nm_min", {}) if isinstance(rec.get("etch_rates_nm_min", {}), dict) else {},
                        "deposition_conformality": rec.get("deposition_conformality", {}) if isinstance(rec.get("deposition_conformality", {}), dict) else {},
                        "cmp_selectivity": rec.get("cmp_selectivity", {}) if isinstance(rec.get("cmp_selectivity", {}), dict) else {},
                        "composition": rec.get("composition", {}) if isinstance(rec.get("composition", {}), dict) else {},
                        "record": rec,
                    }
                )

            return {"ok": True, "materials": items, "schema_version": int(_admin_config_schema_version(cfg))}

    def admin_materials_upsert(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        """Upsert a built-in override or a custom material record."""

        kind = str(payload.get("kind", payload.get("mode", "")) or "").strip().lower()
        key = str(payload.get("key", payload.get("name", "")) or "").strip()
        patch = payload.get("patch", payload.get("material", payload.get("record", {})))
        if kind not in {"builtin", "custom", "override"}:
            return {"ok": False, "error": "kind must be builtin/custom"}
        if not key:
            return {"ok": False, "error": "Missing key/name"}
        if not isinstance(patch, dict):
            return {"ok": False, "error": "patch must be an object"}

        lock_path = self.storage_root / "_tcad_library.lock"
        with _file_lock(lock_path, timeout_s=25.0):
            cfg = self._load_admin_cfg_locked()
            mats_cfg = cfg.get("materials")
            if not isinstance(mats_cfg, dict):
                mats_cfg = {}
                cfg["materials"] = mats_cfg
            if not isinstance(mats_cfg.get("overrides"), dict):
                mats_cfg["overrides"] = {}
            if not isinstance(mats_cfg.get("custom"), dict):
                mats_cfg["custom"] = {}
            overrides: Dict[str, Any] = mats_cfg["overrides"]  # type: ignore[assignment]
            custom: Dict[str, Any] = mats_cfg["custom"]  # type: ignore[assignment]

            # Sanitize supported fields (store as JSON-friendly primitives).
            clean: Dict[str, Any] = {}
            if "enabled" in patch:
                clean["enabled"] = bool(patch.get("enabled"))
            if "name" in patch and kind in {"custom"}:
                nm = str(patch.get("name") or "").strip()
                if nm:
                    clean["name"] = nm
            if "surface_group" in patch:
                clean["surface_group"] = str(patch.get("surface_group") or "").strip()
            if "tags" in patch:
                clean["tags"] = _normalize_tags_list(patch.get("tags"))
            if "note" in patch:
                clean["note"] = str(patch.get("note") or "").strip()
            if "density" in patch:
                try:
                    clean["density"] = float(patch.get("density"))
                except Exception:
                    return {"ok": False, "error": "density must be a number"}
            if "refractive_index" in patch:
                try:
                    clean["refractive_index"] = float(patch.get("refractive_index"))
                except Exception:
                    return {"ok": False, "error": "refractive_index must be a number"}
            if "absorb_coeff" in patch:
                try:
                    clean["absorb_coeff"] = float(patch.get("absorb_coeff"))
                except Exception:
                    return {"ok": False, "error": "absorb_coeff must be a number"}
            if "color" in patch:
                rgb = self._parse_rgb01(patch.get("color"))
                if rgb is None:
                    return {"ok": False, "error": "color must be [r,g,b] (0..1 or 0..255) or '#RRGGBB'"}
                clean["color"] = [float(rgb[0]), float(rgb[1]), float(rgb[2])]

            # Advanced maps: accept as-is when dict; deeper validation comes later (Phase 1/3).
            for k_map in ("etch_rates_nm_min", "deposition_conformality", "cmp_selectivity", "composition"):
                if k_map in patch:
                    v = patch.get(k_map)
                    if v is None:
                        clean[k_map] = {}
                    elif isinstance(v, dict):
                        clean[k_map] = v
                    else:
                        return {"ok": False, "error": f"{k_map} must be an object"}

            if kind in {"builtin", "override"}:
                # Store as an override patch keyed by material name (stable identifier).
                cur = overrides.get(key)
                if not isinstance(cur, dict):
                    cur = {}
                cur.update(clean)
                # Empty override => delete (keep config clean).
                if not cur:
                    overrides.pop(key, None)
                else:
                    overrides[key] = cur
            else:
                # Prevent custom materials from colliding with built-in material names/keys.
                try:
                    builtin_names = set(MaterialDatabase()._name_to_id.keys())
                except Exception:
                    builtin_names = set(MaterialDatabase().names())
                proposed_name = str(clean.get("name", "") or "").strip() or str(key)
                if str(key) in builtin_names or proposed_name in builtin_names:
                    return {"ok": False, "error": "custom material conflicts with built-in material name"}
                # Prevent duplicate custom names (keep name->id stable).
                try:
                    for k2, r2 in custom.items():
                        if str(k2) == str(key):
                            continue
                        if not isinstance(r2, dict):
                            continue
                        nm2 = str(r2.get("name") or k2).strip() or str(k2)
                        if nm2 == proposed_name:
                            return {"ok": False, "error": f"custom material name already exists: {proposed_name}"}
                except Exception:
                    pass
                cur = custom.get(key)
                new_rec = not isinstance(cur, dict)
                if not isinstance(cur, dict):
                    cur = {}
                cur.update(clean)
                # Ensure required fields for new custom materials.
                if new_rec:
                    cur.setdefault("name", key)
                    cur.setdefault("enabled", True)
                    # Assign a stable ID (contiguous) if not provided yet.
                    try:
                        used = [int(v.get("id")) for v in custom.values() if isinstance(v, dict) and v.get("id") is not None]
                        used2 = [u for u in used if u >= 0]
                        next_id = (max(used2) + 1) if used2 else len(MaterialDatabase().materials())
                    except Exception:
                        next_id = len(MaterialDatabase().materials())
                    cur.setdefault("id", int(next_id))
                custom[key] = cur

            self._save_admin_cfg_locked(cfg)
            return {"ok": True, "saved": True}

    def admin_materials_delete(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        """Delete an override, or disable a custom material (keeps IDs stable)."""

        kind = str(payload.get("kind", payload.get("mode", "")) or "").strip().lower()
        key = str(payload.get("key", payload.get("name", "")) or "").strip()
        if kind not in {"builtin", "custom", "override"}:
            return {"ok": False, "error": "kind must be builtin/custom"}
        if not key:
            return {"ok": False, "error": "Missing key/name"}

        lock_path = self.storage_root / "_tcad_library.lock"
        with _file_lock(lock_path, timeout_s=25.0):
            cfg = self._load_admin_cfg_locked()
            mats_cfg = cfg.get("materials")
            if not isinstance(mats_cfg, dict):
                return {"ok": True, "deleted": False}
            if kind in {"builtin", "override"}:
                ov = mats_cfg.get("overrides")
                if isinstance(ov, dict):
                    ov.pop(key, None)
            else:
                cu = mats_cfg.get("custom")
                if isinstance(cu, dict) and isinstance(cu.get(key), dict):
                    cu[key]["enabled"] = False
            self._save_admin_cfg_locked(cfg)
            return {"ok": True, "deleted": True}

    def admin_process_steps_list(self) -> Dict[str, Any]:
        lock_path = self.storage_root / "_tcad_library.lock"
        with _file_lock(lock_path, timeout_s=25.0):
            cfg = self._load_admin_cfg_locked()
            ps = cfg.get("process_steps", {}) if isinstance(cfg.get("process_steps"), dict) else {}
            out: List[Dict[str, Any]] = []
            for name in sorted(PROCESS_STEP_FACTORIES.keys()):
                rec = ps.get(name) if isinstance(ps, dict) else None
                roles = rec.get("roles", {}) if isinstance(rec, dict) else {}
                variants = rec.get("variants", {}) if isinstance(rec, dict) else {}
                out.append(
                    {
                        "step_name": name,
                        "has_config": bool(isinstance(rec, dict) and (roles or variants)),
                        "roles_count": len(roles) if isinstance(roles, dict) else 0,
                        "variants_count": len(variants) if isinstance(variants, dict) else 0,
                    }
                )
            return {"ok": True, "steps": out}

    def admin_process_steps_get(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        step_name = str(payload.get("step_name", payload.get("step", "")) or "").strip()
        if not step_name:
            return {"ok": False, "error": "Missing step_name"}
        if step_name not in PROCESS_STEP_FACTORIES:
            return {"ok": False, "error": f"Unknown step_name: {step_name}"}
        lock_path = self.storage_root / "_tcad_library.lock"
        with _file_lock(lock_path, timeout_s=25.0):
            cfg = self._load_admin_cfg_locked()
            ps = cfg.get("process_steps", {}) if isinstance(cfg.get("process_steps"), dict) else {}
            rec = ps.get(step_name) if isinstance(ps, dict) else None
            if not isinstance(rec, dict):
                rec = {"roles": {}, "variants": {}}
            return {"ok": True, "step_name": step_name, "config": rec}

    def admin_process_steps_set(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        step_name = str(payload.get("step_name", payload.get("step", "")) or "").strip()
        if not step_name:
            return {"ok": False, "error": "Missing step_name"}
        if step_name not in PROCESS_STEP_FACTORIES:
            return {"ok": False, "error": f"Unknown step_name: {step_name}"}
        roles = payload.get("roles", {})
        variants = payload.get("variants", {})
        rate_table = payload.get("rate_table", payload.get("rateTable"))
        has_rate_table = ("rate_table" in payload) or ("rateTable" in payload)
        diffusivity_table = payload.get("diffusivity_table", payload.get("diffusivityTable"))
        has_diffusivity_table = ("diffusivity_table" in payload) or ("diffusivityTable" in payload)
        if roles is None:
            roles = {}
        if variants is None:
            variants = {}
        if not isinstance(roles, dict):
            return {"ok": False, "error": "roles must be an object"}
        if not isinstance(variants, dict):
            return {"ok": False, "error": "variants must be an object"}

        # Lightweight validation/sanitize for VariantBuilder: ensure parameter_specs shape is sane.
        allowed_types = {t["type"] for t in (self.process_schema_types().get("parameter_spec_types") or []) if isinstance(t, dict)}

        def _clean_roles(obj: Any) -> Dict[str, Any]:
            if not isinstance(obj, dict):
                return {}
            out: Dict[str, Any] = {}
            for rk, rec0 in obj.items():
                key = str(rk or "").strip()
                if not key:
                    continue
                rec = rec0 if isinstance(rec0, dict) else {}
                allowed0 = rec.get("allowed_materials", rec.get("allowed", []))
                allowed: List[str] = []
                if isinstance(allowed0, list):
                    allowed = [str(x).strip() for x in allowed0 if str(x).strip()]
                allowed_ids0 = rec.get("allowed_material_ids", rec.get("allowed_ids", []))
                allowed_ids: List[int] = []
                if isinstance(allowed_ids0, list):
                    for x in allowed_ids0:
                        try:
                            allowed_ids.append(int(x))
                        except Exception:
                            continue
                groups0 = rec.get("allowed_surface_groups", rec.get("allowed_groups", []))
                groups: List[str] = []
                if isinstance(groups0, list):
                    groups = [str(x).strip() for x in groups0 if str(x).strip()]
                allowed_tags = _normalize_tags_list(rec.get("allowed_tags"))
                out[key] = {
                    "role_key": key,
                    "label": str(rec.get("label", "") or ""),
                    "default_material": str(rec.get("default_material", rec.get("default", "")) or "").strip(),
                    "allowed_materials": allowed,
                    "allowed_material_ids": allowed_ids,
                    "allowed_surface_groups": groups,
                    "allowed_tags": allowed_tags,
                }
            return out

        def _clean_specs(specs_in: Any) -> List[Dict[str, Any]]:
            if not isinstance(specs_in, list):
                return []
            out: List[Dict[str, Any]] = []
            for it in specs_in:
                if not isinstance(it, dict):
                    continue
                key = str(it.get("key", "") or "").strip()
                label = str(it.get("label", key) or key).strip() or key
                typ = str(it.get("type", "") or "").strip()
                if not key:
                    continue
                if typ not in allowed_types:
                    continue
                spec: Dict[str, Any] = {
                    "key": key,
                    "label": label,
                    "type": typ,
                    "default": it.get("default"),
                    "minimum": it.get("minimum"),
                    "maximum": it.get("maximum"),
                    "choices": it.get("choices"),
                    "decimals": int(it.get("decimals", 2) or 2),
                    "step": it.get("step"),
                    "units": str(it.get("units") or ""),
                    "tooltip": str(it.get("tooltip") or ""),
                }
                out.append(spec)
            return out

        def _clean_material_roles(obj: Any) -> Dict[str, Any]:
            if not isinstance(obj, dict):
                return {}
            out: Dict[str, Any] = {}
            for rk, rec0 in obj.items():
                key = str(rk or "").strip()
                if not key:
                    continue
                rec = rec0 if isinstance(rec0, dict) else {}
                allowed0 = rec.get("allowed_materials", rec.get("allowed", []))
                allowed: List[str] = []
                if isinstance(allowed0, list):
                    allowed = [str(x).strip() for x in allowed0 if str(x).strip()]
                allowed_ids0 = rec.get("allowed_material_ids", rec.get("allowed_ids", []))
                allowed_ids: List[int] = []
                if isinstance(allowed_ids0, list):
                    for x in allowed_ids0:
                        try:
                            allowed_ids.append(int(x))
                        except Exception:
                            continue
                groups0 = rec.get("allowed_surface_groups", rec.get("allowed_groups", []))
                groups: List[str] = []
                if isinstance(groups0, list):
                    groups = [str(x).strip() for x in groups0 if str(x).strip()]
                allowed_tags = _normalize_tags_list(rec.get("allowed_tags"))
                out[key] = {
                    "role_key": key,
                    "label": str(rec.get("label", "") or ""),
                    "default_material": str(rec.get("default_material", rec.get("default", "")) or "").strip(),
                    "allowed_materials": allowed,
                    "allowed_material_ids": allowed_ids,
                    "allowed_surface_groups": groups,
                    "allowed_tags": allowed_tags,
                }
            return out

        clean_roles = _clean_roles(roles)
        clean_variants: Dict[str, Any] = {}
        for vid, vrec0 in variants.items():
            vid_s = str(vid or "").strip()
            if not vid_s:
                continue
            if not isinstance(vrec0, dict):
                continue
            vrec = dict(vrec0)
            vrec["id"] = str(vrec.get("id", vid_s) or vid_s)
            vrec["label"] = str(vrec.get("label", vrec["id"]) or vrec["id"])
            vrec["enabled"] = bool(vrec.get("enabled", False))
            vrec["parameter_specs"] = _clean_specs(vrec.get("parameter_specs"))
            if not isinstance(vrec.get("defaults"), dict):
                vrec["defaults"] = {}
            if "inherits" in vrec:
                vrec["inherits"] = str(vrec.get("inherits") or "").strip()
            if "mapping" in vrec:
                vrec["mapping"] = vrec.get("mapping") if isinstance(vrec.get("mapping"), dict) else {}
            if "material_roles" in vrec:
                vrec["material_roles"] = _clean_material_roles(vrec.get("material_roles"))
            clean_variants[vid_s] = vrec

        lock_path = self.storage_root / "_tcad_library.lock"
        with _file_lock(lock_path, timeout_s=25.0):
            cfg = self._load_admin_cfg_locked()
            ps = cfg.get("process_steps")
            if not isinstance(ps, dict):
                ps = {}
                cfg["process_steps"] = ps
            # Preserve existing variant versions unless the caller explicitly provides one.
            prev_vars: Dict[str, Any] = {}
            try:
                prev_rec = ps.get(step_name) if isinstance(ps, dict) else None
                if isinstance(prev_rec, dict) and isinstance(prev_rec.get("variants"), dict):
                    prev_vars = prev_rec.get("variants", {})  # type: ignore[assignment]
            except Exception:
                prev_vars = {}
            for vid, vrec in clean_variants.items():
                if not isinstance(vrec, dict):
                    continue
                try:
                    inc_ver = int(vrec.get("version", 0) or 0)
                except Exception:
                    inc_ver = 0
                prev_ver = 1
                try:
                    pv = prev_vars.get(vid)
                    if isinstance(pv, dict):
                        prev_ver = int(pv.get("version", 1) or 1)
                except Exception:
                    prev_ver = 1
                if inc_ver <= 0:
                    vrec["version"] = int(prev_ver if prev_ver > 0 else 1)
                else:
                    vrec["version"] = int(inc_ver)

            base_rec = ps.get(step_name) if isinstance(ps, dict) else None
            out_rec: Dict[str, Any] = dict(base_rec) if isinstance(base_rec, dict) else {}
            out_rec["roles"] = clean_roles
            out_rec["variants"] = clean_variants
            if has_rate_table:
                out_rec["rate_table"] = rate_table if isinstance(rate_table, dict) else {}
            if has_diffusivity_table:
                out_rec["diffusivity_table"] = diffusivity_table if isinstance(diffusivity_table, dict) else {}
            ps[step_name] = out_rec
            self._save_admin_cfg_locked(cfg)
            return {"ok": True, "saved": True}

