    def admin_process_variants_upsert(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        """Upsert a single variant record under a step (admin-only)."""

        step_name = str(payload.get("step_name", payload.get("step", "")) or "").strip()
        vid = str(payload.get("variant_id", payload.get("variant", payload.get("id", ""))) or "").strip()
        patch = payload.get("patch", payload.get("variant", payload.get("record", {})))
        if not step_name:
            return {"ok": False, "error": "Missing step_name"}
        if step_name not in PROCESS_STEP_FACTORIES:
            return {"ok": False, "error": f"Unknown step_name: {step_name}"}
        if not vid:
            return {"ok": False, "error": "Missing variant_id"}
        if not isinstance(patch, dict):
            return {"ok": False, "error": "patch must be an object"}

        allowed_types = {t["type"] for t in (self.process_schema_types().get("parameter_spec_types") or []) if isinstance(t, dict)}

        def _clean_specs(specs_in: Any) -> List[Dict[str, Any]]:
            if not isinstance(specs_in, list):
                return []
            out: List[Dict[str, Any]] = []
            for it in specs_in:
                if not isinstance(it, dict):
                    continue
                key = str(it.get("key", "") or "").strip()
                label = str(it.get("label", key) or key).strip() or key
                typ = str(it.get("type", "") or "").strip()
                if not key:
                    continue
                if typ not in allowed_types:
                    continue
                out.append(
                    {
                        "key": key,
                        "label": label,
                        "type": typ,
                        "default": it.get("default"),
                        "minimum": it.get("minimum"),
                        "maximum": it.get("maximum"),
                        "choices": it.get("choices"),
                        "decimals": int(it.get("decimals", 2) or 2),
                        "step": it.get("step"),
                        "units": str(it.get("units") or ""),
                        "tooltip": str(it.get("tooltip") or ""),
                    }
                )
            return out

        def _clean_material_roles(obj: Any) -> Dict[str, Any]:
            if not isinstance(obj, dict):
                return {}
            out: Dict[str, Any] = {}
            for rk, rec0 in obj.items():
                key = str(rk or "").strip()
                if not key:
                    continue
                rec = rec0 if isinstance(rec0, dict) else {}
                allowed0 = rec.get("allowed_materials", rec.get("allowed", []))
                allowed: List[str] = []
                if isinstance(allowed0, list):
                    allowed = [str(x).strip() for x in allowed0 if str(x).strip()]
                allowed_ids0 = rec.get("allowed_material_ids", rec.get("allowed_ids", []))
                allowed_ids: List[int] = []
                if isinstance(allowed_ids0, list):
                    for x in allowed_ids0:
                        try:
                            allowed_ids.append(int(x))
                        except Exception:
                            continue
                groups0 = rec.get("allowed_surface_groups", rec.get("allowed_groups", []))
                groups: List[str] = []
                if isinstance(groups0, list):
                    groups = [str(x).strip() for x in groups0 if str(x).strip()]
                allowed_tags = _normalize_tags_list(rec.get("allowed_tags"))
                out[key] = {
                    "role_key": key,
                    "label": str(rec.get("label", "") or ""),
                    "default_material": str(rec.get("default_material", rec.get("default", "")) or "").strip(),
                    "allowed_materials": allowed,
                    "allowed_material_ids": allowed_ids,
                    "allowed_surface_groups": groups,
                    "allowed_tags": allowed_tags,
                }
            return out

        lock_path = self.storage_root / "_tcad_library.lock"
        with _file_lock(lock_path, timeout_s=25.0):
            cfg = self._load_admin_cfg_locked()
            ps = cfg.get("process_steps")
            if not isinstance(ps, dict):
                ps = {}
                cfg["process_steps"] = ps
            rec = ps.get(step_name)
            if not isinstance(rec, dict):
                rec = {"roles": {}, "variants": {}}
            variants = rec.get("variants")
            if not isinstance(variants, dict):
                variants = {}
                rec["variants"] = variants

            cur = variants.get(vid)
            if not isinstance(cur, dict):
                cur = {}
            # Keep stable identity (id/label) but allow renaming label.
            cur["id"] = str(patch.get("id", cur.get("id", vid)) or vid)
            cur["label"] = str(patch.get("label", cur.get("label", cur["id"])) or cur["id"])
            if "enabled" in patch:
                cur["enabled"] = bool(patch.get("enabled"))
            else:
                cur["enabled"] = bool(cur.get("enabled", False))
            if "parameter_specs" in patch:
                cur["parameter_specs"] = _clean_specs(patch.get("parameter_specs"))
            if "defaults" in patch:
                cur["defaults"] = patch.get("defaults") if isinstance(patch.get("defaults"), dict) else {}
            if "inherits" in patch:
                cur["inherits"] = str(patch.get("inherits") or "").strip()
            if "mapping" in patch:
                cur["mapping"] = patch.get("mapping") if isinstance(patch.get("mapping"), dict) else {}
            if "material_roles" in patch:
                cur["material_roles"] = _clean_material_roles(patch.get("material_roles"))
            if "version" in patch:
                try:
                    vv = int(patch.get("version", 0) or 0)
                except Exception:
                    vv = 0
                if vv > 0:
                    cur["version"] = int(vv)
            # Default version for new records / missing values.
            try:
                vv2 = int(cur.get("version", 0) or 0)
            except Exception:
                vv2 = 0
            if vv2 <= 0:
                cur["version"] = 1

            variants[vid] = cur
            ps[step_name] = rec
            self._save_admin_cfg_locked(cfg)
            return {"ok": True, "saved": True, "step_name": step_name, "variant_id": vid}

    def admin_process_variants_publish(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        """Create a per-variant published snapshot (for rollback without full backups)."""

        step_name = str(payload.get("step_name", payload.get("step", "")) or "").strip()
        vid = str(payload.get("variant_id", payload.get("variant", payload.get("id", ""))) or "").strip()
        note = str(payload.get("note", payload.get("message", "")) or "").strip()
        try:
            max_keep = int(payload.get("max_keep", 30) or 30)
        except Exception:
            max_keep = 30
        max_keep = int(np.clip(max_keep, 5, 200))
        if not step_name:
            return {"ok": False, "error": "Missing step_name"}
        if step_name not in PROCESS_STEP_FACTORIES:
            return {"ok": False, "error": f"Unknown step_name: {step_name}"}
        if not vid:
            return {"ok": False, "error": "Missing variant_id"}

        def _strip_meta(vrec_in: Dict[str, Any]) -> Dict[str, Any]:
            out = copy.deepcopy(vrec_in)
            for k in ("revisions", "published_version", "published_ts", "published_time", "rollback_ts", "rollback_time"):
                out.pop(k, None)
            return out

        lock_path = self.storage_root / "_tcad_library.lock"
        with _file_lock(lock_path, timeout_s=25.0):
            cfg = self._load_admin_cfg_locked()
            ps = cfg.get("process_steps", {}) if isinstance(cfg.get("process_steps"), dict) else {}
            rec = ps.get(step_name) if isinstance(ps, dict) else None
            variants = rec.get("variants", {}) if isinstance(rec, dict) else {}
            if not isinstance(variants, dict) or vid not in variants:
                return {"ok": False, "error": f"Variant not found: {vid}"}
            vrec = variants.get(vid)
            if not isinstance(vrec, dict):
                return {"ok": False, "error": f"Invalid variant record: {vid}"}

            revisions = vrec.get("revisions")
            if not isinstance(revisions, list):
                revisions = []
            max_rev_ver = 0
            try:
                for ent in revisions:
                    if not isinstance(ent, dict):
                        continue
                    try:
                        vv = int(ent.get("version", 0) or 0)
                    except Exception:
                        vv = 0
                    max_rev_ver = max(max_rev_ver, vv)
            except Exception:
                max_rev_ver = 0
            try:
                cur_ver = int(vrec.get("version", 0) or 0)
            except Exception:
                cur_ver = 0
            if cur_ver <= 0:
                cur_ver = 1
            try:
                pub_ver0 = int(vrec.get("published_version", 0) or 0)
            except Exception:
                pub_ver0 = 0

            new_ver = max(cur_ver, max_rev_ver, pub_ver0) + 1
            vrec["version"] = int(new_ver)
            vrec["published_version"] = int(new_ver)
            ts = float(time.time())
            vrec["published_ts"] = ts
            vrec["published_time"] = datetime.datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M:%S")

            snapshot = _strip_meta(vrec)
            snapshot["version"] = int(new_ver)
            snapshot["id"] = str(snapshot.get("id", vid) or vid)
            snapshot["label"] = str(snapshot.get("label", snapshot["id"]) or snapshot["id"])

            revisions.append(
                {
                    "version": int(new_ver),
                    "ts": ts,
                    "time": vrec.get("published_time"),
                    "note": note,
                    "variant": snapshot,
                }
            )
            if len(revisions) > max_keep:
                revisions = revisions[-max_keep:]
            vrec["revisions"] = revisions

            variants[vid] = vrec
            if isinstance(rec, dict):
                rec["variants"] = variants
                ps[step_name] = rec  # type: ignore[index]
                cfg["process_steps"] = ps
            self._save_admin_cfg_locked(cfg)
            return {
                "ok": True,
                "published": True,
                "step_name": step_name,
                "variant_id": vid,
                "version": int(new_ver),
                "revisions": int(len(revisions)),
            }

    def admin_process_variants_rollback(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        """Rollback a variant to a previously published snapshot (by version)."""

        step_name = str(payload.get("step_name", payload.get("step", "")) or "").strip()
        vid = str(payload.get("variant_id", payload.get("variant", payload.get("id", ""))) or "").strip()
        try:
            want_version = int(payload.get("version", payload.get("to_version", 0)) or 0)
        except Exception:
            want_version = 0
        if not step_name:
            return {"ok": False, "error": "Missing step_name"}
        if step_name not in PROCESS_STEP_FACTORIES:
            return {"ok": False, "error": f"Unknown step_name: {step_name}"}
        if not vid:
            return {"ok": False, "error": "Missing variant_id"}

        lock_path = self.storage_root / "_tcad_library.lock"
        with _file_lock(lock_path, timeout_s=25.0):
            cfg = self._load_admin_cfg_locked()
            ps = cfg.get("process_steps", {}) if isinstance(cfg.get("process_steps"), dict) else {}
            rec = ps.get(step_name) if isinstance(ps, dict) else None
            variants = rec.get("variants", {}) if isinstance(rec, dict) else {}
            if not isinstance(variants, dict) or vid not in variants:
                return {"ok": False, "error": f"Variant not found: {vid}"}
            vrec = variants.get(vid)
            if not isinstance(vrec, dict):
                return {"ok": False, "error": f"Invalid variant record: {vid}"}
            revisions = vrec.get("revisions")
            if not isinstance(revisions, list) or not revisions:
                return {"ok": False, "error": "No published snapshots found for this variant"}

            target: Optional[Dict[str, Any]] = None
            if want_version > 0:
                for ent in reversed(revisions):
                    if not isinstance(ent, dict):
                        continue
                    try:
                        vv = int(ent.get("version", 0) or 0)
                    except Exception:
                        vv = 0
                    if vv == want_version:
                        target = ent
                        break
            if target is None:
                # Fallback: rollback to last snapshot.
                ent = revisions[-1]
                target = ent if isinstance(ent, dict) else None
            if not target:
                return {"ok": False, "error": "Invalid snapshot entry"}
            snap = target.get("variant")
            if not isinstance(snap, dict) or not snap:
                return {"ok": False, "error": "Snapshot is missing variant payload"}

            restored = copy.deepcopy(snap)
            # Preserve history + keep required identity.
            restored["revisions"] = revisions
            restored["id"] = str(restored.get("id", vid) or vid)
            restored["label"] = str(restored.get("label", restored["id"]) or restored["id"])
            restored["enabled"] = bool(restored.get("enabled", False))
            if not isinstance(restored.get("parameter_specs"), list):
                restored["parameter_specs"] = []
            if not isinstance(restored.get("defaults"), dict):
                restored["defaults"] = {}
            if "inherits" in restored:
                restored["inherits"] = str(restored.get("inherits") or "").strip()
            if not isinstance(restored.get("mapping"), dict):
                restored["mapping"] = {}
            if not isinstance(restored.get("material_roles"), dict):
                restored["material_roles"] = {}

            try:
                to_ver = int(restored.get("version", 0) or 0)
            except Exception:
                to_ver = 0
            if to_ver <= 0:
                try:
                    to_ver = int(target.get("version", 0) or 0)
                except Exception:
                    to_ver = 0
            ts = float(time.time())
            restored["published_version"] = int(to_ver) if to_ver > 0 else 0
            restored["published_ts"] = ts
            restored["published_time"] = datetime.datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M:%S")
            restored["rollback_ts"] = ts
            restored["rollback_time"] = restored.get("published_time")

            variants[vid] = restored
            if isinstance(rec, dict):
                rec["variants"] = variants
                ps[step_name] = rec  # type: ignore[index]
                cfg["process_steps"] = ps
            self._save_admin_cfg_locked(cfg)
            return {
                "ok": True,
                "rolled_back": True,
                "step_name": step_name,
                "variant_id": vid,
                "version": int(to_ver) if to_ver > 0 else 0,
            }

    def admin_process_variants_delete(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        """Delete or disable a variant record (admin-only)."""

        step_name = str(payload.get("step_name", payload.get("step", "")) or "").strip()
        vid = str(payload.get("variant_id", payload.get("variant", payload.get("id", ""))) or "").strip()
        hard = bool(payload.get("hard", False))
        if not step_name:
            return {"ok": False, "error": "Missing step_name"}
        if step_name not in PROCESS_STEP_FACTORIES:
            return {"ok": False, "error": f"Unknown step_name: {step_name}"}
        if not vid:
            return {"ok": False, "error": "Missing variant_id"}
        lock_path = self.storage_root / "_tcad_library.lock"
        with _file_lock(lock_path, timeout_s=25.0):
            cfg = self._load_admin_cfg_locked()
            ps = cfg.get("process_steps", {}) if isinstance(cfg.get("process_steps"), dict) else {}
            rec = ps.get(step_name) if isinstance(ps, dict) else None
            variants = rec.get("variants", {}) if isinstance(rec, dict) else {}
            if not isinstance(variants, dict) or vid not in variants:
                return {"ok": False, "error": f"Variant not found: {vid}"}
            if hard:
                variants.pop(vid, None)
            else:
                vrec = variants.get(vid)
                if isinstance(vrec, dict):
                    vrec["enabled"] = False
                    variants[vid] = vrec
            if isinstance(rec, dict):
                rec["variants"] = variants
                ps[step_name] = rec  # type: ignore[index]
                cfg["process_steps"] = ps
            self._save_admin_cfg_locked(cfg)
            return {"ok": True, "deleted": True, "hard": hard, "step_name": step_name, "variant_id": vid}

    def admin_preset_sequences_list(self) -> Dict[str, Any]:
        lock_path = self.storage_root / "_tcad_library.lock"
        with _file_lock(lock_path, timeout_s=25.0):
            cfg = self._load_admin_cfg_locked()
            pseq = cfg.get("preset_sequences", {}) if isinstance(cfg.get("preset_sequences"), dict) else {}
            seqs = pseq.get("sequences", {}) if isinstance(pseq.get("sequences"), dict) else {}
            out: List[Dict[str, Any]] = []
            if isinstance(seqs, dict):
                for pid0 in sorted(seqs.keys(), key=lambda s: str(s).lower()):
                    pid = str(pid0 or "").strip()
                    if not pid:
                        continue
                    rec = seqs.get(pid0)
                    if not isinstance(rec, dict):
                        continue
                    label = str(rec.get("label", pid) or pid).strip() or pid
                    enabled = bool(rec.get("enabled", True))
                    steps = rec.get("steps", [])
                    steps_count = len(steps) if isinstance(steps, list) else 0
                    out.append({"preset_id": pid, "label": label, "enabled": enabled, "steps_count": int(steps_count)})
