    def admin_preset_sequences_upsert(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        pid = str(payload.get("preset_id", payload.get("id", "")) or "").strip()
        patch = payload.get("patch", payload.get("preset", payload.get("record", {})))
        if not pid:
            return {"ok": False, "error": "Missing preset_id"}
        if not isinstance(patch, dict):
            return {"ok": False, "error": "preset patch must be an object"}

        label = str(patch.get("label", pid) or pid).strip() or pid
        enabled = bool(patch.get("enabled", True))
        steps_in = patch.get("steps", [])
        steps: List[Dict[str, Any]] = []
        if isinstance(steps_in, list):
            for st0 in steps_in:
                if not isinstance(st0, dict):
                    continue
                name = str(st0.get("name", st0.get("step", st0.get("step_name", ""))) or "").strip()
                if not name or name not in PROCESS_STEP_FACTORIES:
                    continue
                params = st0.get("params", {})
                if not isinstance(params, dict):
                    params = {}
                steps.append({"name": name, "enabled": bool(st0.get("enabled", True)), "params": params})

        lock_path = self.storage_root / "_tcad_library.lock"
        with _file_lock(lock_path, timeout_s=25.0):
            cfg = self._load_admin_cfg_locked()
            pseq = cfg.get("preset_sequences")
            if not isinstance(pseq, dict):
                pseq = {"version": int(_PRESET_SEQUENCES_VERSION), "sequences": {}}
                cfg["preset_sequences"] = pseq
            if "version" not in pseq:
                pseq["version"] = int(_PRESET_SEQUENCES_VERSION)
            seqs = pseq.get("sequences")
            if not isinstance(seqs, dict):
                seqs = {}
                pseq["sequences"] = seqs

            prev = seqs.get(pid)
            created_at = ""
            if isinstance(prev, dict):
                created_at = str(prev.get("created_at") or "")

            rec: Dict[str, Any] = {
                "id": pid,
                "label": label,
                "enabled": enabled,
                "steps": steps,
                "created_at": created_at or _webui_timestamp(),
                "updated_at": _webui_timestamp(),
            }
            seqs[pid] = rec
            pseq["sequences"] = seqs
            cfg["preset_sequences"] = pseq

            self._save_admin_cfg_locked(cfg)
            return {"ok": True, "saved": True, "preset_id": pid}

