        state.slice2dMaxY = axisMax('Y');
        state.slice2dMaxZ = axisMax('Z');
        state.slice2dIndexX = clampInt(state.slice2dIndexX, 0, state.slice2dMaxX);
        state.slice2dIndexY = clampInt(state.slice2dIndexY, 0, state.slice2dMaxY);
